import React, { useState } from 'react';
import { AnalyticsBrowser } from '@segment/analytics-next';

// Initialize analytics
const analytics = AnalyticsBrowser.load({ writeKey: 'YOUR_SEGMENT_WRITE_KEY' });

// Mock authentication service (replace with actual backend in real app)
const mockAuthService = {
  signup: async (email, password, companyName) => {
    // Simulate user creation
    const userId = `user_${Math.random().toString(36).substr(2, 9)}`;
    return {
      id: userId,
      email,
      companyName
    };
  },
  login: async (email, password) => {
    // Simulate login
    const userId = `user_${Math.random().toString(36).substr(2, 9)}`;
    return {
      id: userId,
      email
    };
  }
};

// Main App Component
const SegmentAuthApp = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [view, setView] = useState('login'); // 'login', 'signup'
  
  // Form state
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [companyName, setCompanyName] = useState('');

  // Signup Handler
  const handleSignup = async (e) => {
    e.preventDefault();

    try {
      const user = await mockAuthService.signup(email, password, companyName);
      
      // Segment Identify and Group calls
      await analytics.identify(user.id, {
        email: user.email,
      });

      await analytics.group(companyName, {
        name: companyName,
      });

      setCurrentUser(user);
      setIsLoggedIn(true);
    } catch (error) {
      console.error('Signup failed', error);
      alert('Signup failed');
    }
  };

  // Login Handler
  const handleLogin = async (e) => {
    e.preventDefault();

    try {
      const user = await mockAuthService.login(email, password);
      
      // Segment Identify call
      await analytics.identify(user.id, {
        email: user.email,
      });

      setCurrentUser(user);
      setIsLoggedIn(true);
    } catch (error) {
      console.error('Login failed', error);
      alert('Login failed');
    }
  };

  // Logout Handler
  const handleLogout = () => {
    // Segment reset
    analytics.reset();
    
    setIsLoggedIn(false);
    setCurrentUser(null);
    setView('login');
    setEmail('');
    setPassword('');
    setCompanyName('');
  };

  // Render Login Form
  const LoginForm = () => (
    <div className="max-w-md mx-auto mt-10 p-6 bg-white rounded-lg shadow-md">
      <h2 className="text-2xl font-bold mb-6 text-center">Login</h2>
      <form onSubmit={handleLogin}>
        <div className="mb-4">
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="email">
            Email
          </label>
          <input 
            type="email" 
            id="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required 
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
          />
        </div>
        <div className="mb-6">
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="password">
            Password
          </label>
          <input 
            type="password"
            id="password" 
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required 
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 mb-3 leading-tight focus:outline-none focus:shadow-outline"
          />
        </div>
        <div className="flex items-center justify-between">
          <button 
            type="submit"
            className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline"
          >
            Sign In
          </button>
          <button 
            type="button"
            onClick={() => setView('signup')}
            className="inline-block align-baseline font-bold text-sm text-blue-500 hover:text-blue-800"
          >
            Need an account?
          </button>
        </div>
      </form>
    </div>
  );

  // Render Signup Form
  const SignupForm = () => (
    <div className="max-w-md mx-auto mt-10 p-6 bg-white rounded-lg shadow-md">
      <h2 className="text-2xl font-bold mb-6 text-center">Sign Up</h2>
      <form onSubmit={handleSignup}>
        <div className="mb-4">
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="signup-email">
            Email
          </label>
          <input 
            type="email"
            id="signup-email" 
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required 
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
          />
        </div>
        <div className="mb-4">
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="signup-password">
            Password
          </label>
          <input 
            type="password"
            id="signup-password" 
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required 
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 mb-3 leading-tight focus:outline-none focus:shadow-outline"
          />
        </div>
        <div className="mb-6">
          <label className="block text-gray-700 text-sm font-bold mb-2" htmlFor="company-name">
            Company/Team Name
          </label>
          <input 
            type="text"
            id="company-name" 
            value={companyName}
            onChange={(e) => setCompanyName(e.target.value)}
            required 
            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
          />
        </div>
        <div className="flex items-center justify-between">
          <button 
            type="submit"
            className="bg-green-500 hover:bg-green-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline"
          >
            Create Account
          </button>
          <button 
            type="button"
            onClick={() => setView('login')}
            className="inline-block align-baseline font-bold text-sm text-blue-500 hover:text-blue-800"
          >
            Already have an account?
          </button>
        </div>
      </form>
    </div>
  );

  // Render Logged In View
  const LoggedInView = () => (
    <div className="max-w-md mx-auto mt-10 p-6 bg-white rounded-lg shadow-md text-center">
      <h2 className="text-2xl font-bold mb-6">Welcome!</h2>
      <p className="mb-4">Logged in as: {currentUser?.email}</p>
      {currentUser?.companyName && (
        <p className="mb-4">Company: {currentUser.companyName}</p>
      )}
      <button 
        onClick={handleLogout}
        className="bg-red-500 hover:bg-red-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline"
      >
        Logout
      </button>
    </div>
  );

  return (
    <div className="min-h-screen bg-gray-100 flex items-center justify-center">
      {isLoggedIn ? (
        <LoggedInView />
      ) : (
        view === 'login' ? <LoginForm /> : <SignupForm />
      )}
    </div>
  );
};

// Main App Component (no need for Analytics wrapper anymore)
const App = () => {
  return <SegmentAuthApp />;
};

export default App; 